function getWrestlerTemplate(name) {
  return wrestlerDatabase[name] || null;
}

function spawnWrestlerFromDB(id, overrides = {}) {
  const template = wrestlerDatabase[id];
  if (!template) { console.warn(`[Roster] No template for ${id}`); return null; }
  const data = { ...template, ...overrides };
  // Normalize brand casing
  if (data.brand === "Grandslam") data.brand = "GrandSlam";
  const w = createWrestler(data);
  // Enrich with new schema fields
  w.level = data.level || 1;
  w.xp = data.xp || 0;
  w.maxXp = data.maxXp || 1000;
  w.condition = data.condition || "Fresh";
  w.personality = data.personality || "Balanced";
  w.style = data.style || "Balanced";
  w.finishers = data.finishers || [];
  w.history = data.history || { titles: [], rivalries: [], winRate: "55%" };
  w.tier = data.tier || "Midcard";
  return w;
}

function createWrestler(data) {
    const basePop = data.popularity || 55;
    return {
        name: data.name || "Unnamed",
        brand: data.brand || "Free Agents",
        color: data.color || BRAND_COLORS[data.brand] || "#888888",
        popularity: basePop,
        hot: data.hot || 0,
        inRing: data.inRing || data.strength || 60,
        promo: data.promo || data.charisma || 50,
        stamina: data.stamina || 60,
        charisma: data.charisma || 50,
        careerRating: data.careerRating || Math.max(45, Math.floor(basePop * 0.65 + (data.inRing || 60) * 0.25)),
        fatigue: data.fatigue || 0,
        streak: data.streak || 0,
        fanBonus: data.fanBonus || Math.floor(basePop / 5),
        matchHistory: data.matchHistory || {},
        equipment: data.equipment || { type: Math.random() > 0.5 ? "weapon" : "attire", level: Math.max(1, Math.min(3, Math.floor(basePop / 30))), name: "Basic Gear" },
        trainingPoints: data.trainingPoints || 3,
        stats: data.stats || {}
    };
}

