// ===== FOUNDATION SYSTEMS =====
function getBrandValue(brand) { return game.brandValues[brand] || 40; }
function adjustBrandValue(brand, amount) {
    if (!game.brandValues[brand]) game.brandValues[brand] = 40;
    game.brandValues[brand] = Math.max(20, Math.min(100, game.brandValues[brand] + amount));
    return game.brandValues[brand];
}
function updateBrandValuesAfterShow(brand, avgPerf) {
    let change = 0;
    if (avgPerf >= 4.5) change = 2.2;
    else if (avgPerf >= 4.0) change = 1.4;
    else if (avgPerf >= 3.5) change = 0.5;
    else if (avgPerf < 3.0) change = -1.5;
    const newVal = adjustBrandValue(brand, change);
    return { brand, change: change.toFixed(1), newValue: newVal };
}

function getBelt(key) { return game.belts[key] || null; }
function changeChampion(beltKey, newChampion) {
    const belt = getBelt(beltKey);
    if (!belt) return false;
    if (belt.champion) {
        if (!belt.history) belt.history = [];
        belt.history.push({ champion: belt.champion, defenses: belt.defenses || 0, endDay: game.date.day });
    }
    const old = belt.champion;
    belt.champion = newChampion;
    belt.defenses = 0;
    belt.lastChangeDay = game.date.day;
    const nw = getWrestler(newChampion);
    if (nw) {
        belt.prestige = Math.min(100, belt.prestige + 4);
        nw.popularity = Math.min(100, nw.popularity + 6);
    }
    return { old, new: newChampion };
}
function defendTitle(beltKey, winnerName) {
    const belt = getBelt(beltKey);
    if (!belt || belt.champion !== winnerName) return false;
    belt.defenses = (belt.defenses || 0) + 1;
    belt.prestige = Math.min(100, belt.prestige + 1.5);
    const champ = getWrestler(winnerName);
    if (champ) {
        champ.popularity = Math.min(100, champ.popularity + 3);
        champ.hot = Math.min(6, (champ.hot || 0) + 1);
    }
    return true;
}
function getBeltPrestigeBonus(wrestlerName) {
    let bonus = 0;
    Object.keys(game.belts || {}).forEach(key => {
        if (game.belts[key].champion === wrestlerName) {
            bonus += Math.floor(game.belts[key].prestige / 20);
        }
    });
    return Math.min(8, bonus);
}

