function getWrestler(name) { return game.wrestlers.find(w => w.name === name); }

// === v44 CATEGORIZED LOGGER ===
const JPE_LOG = {
    info:     (msg) => console.log(`%c[JPE] ${msg}`, "color:#aaa"),
    brand:    (msg) => console.log(`%c[Brand] ${msg}`, "color:#ff6200"),
    training: (msg) => console.log(`%c[Training] ${msg}`, "color:#00ff85"),
    economy:  (msg) => console.log(`%c[Economy] ${msg}`, "color:#ffd700"),
    warn:     (msg) => console.warn(`[JPE Warning] ${msg}`),
    dev:      (msg) => console.log(`%c[Dev] ${msg}`, "color:#00aaff")
};

// === v44 WRESTLER DEVELOPMENT LOG ===
function logWrestlerDevelopment(name, type, amount, reason = "") {
    const w = getWrestler(name);
    if (!w) return;
    if (!w.devLog) w.devLog = [];
    w.devLog.push({
        day: game.date.day,
        type,           // "passive", "manual", "show", "injury", etc.
        amount,
        reason
    });
    // Keep log reasonable size
    if (w.devLog.length > 25) w.devLog.shift();
}

// === v44 WEEKLY RECAP (Background QoL) ===
function checkWeeklyRecap() {
    if (game.date.day % 7 !== 0) return;

    const recap = {
        week: Math.floor((game.date.day + (game.date.month * 30)) / 7),
        topPerformers: [],
        brandStandings: {},
        totalIncome: 0,
        showsRun: game.showsSimulated || 0
    };

    // Top 3 by career rating this week
    const sorted = [...game.wrestlers].sort((a, b) => (b.careerRating || 0) - (a.careerRating || 0));
    recap.topPerformers = sorted.slice(0, 3).map(w => ({
        name: w.name,
        brand: w.brand,
        career: w.careerRating
    }));

    // Brand value snapshot
    Object.keys(game.brandValues || {}).forEach(b => {
        recap.brandStandings[b] = game.brandValues[b];
    });

    if (!game.weeklyRecaps) game.weeklyRecaps = [];
    game.weeklyRecaps.push(recap);

    // Keep only last 8 weeks
    if (game.weeklyRecaps.length > 8) game.weeklyRecaps.shift();

    JPE_LOG.info(`Weekly recap saved (week ${recap.week})`);
    if (typeof quickToast === "function") {
        quickToast("Weekly Recap ready — check Legacy tab", "#00aaff");
    }
}

// ==================== v84 ROSTER EXPANSION: Signing & Migration ====================
function migrateWrestlerToNewSchema(w) {
  if (!w.level) w.level = Math.max(1, Math.floor((w.careerRating || 60) / 8));
  if (!w.xp) w.xp = Math.floor((w.level || 1) * 180 + Math.random() * 120);
  if (!w.maxXp) w.maxXp = w.level * 250 + 500;
  if (!w.condition) w.condition = (w.fatigue || 0) > 60 ? "Injured" : (w.hot || 0) > 3 ? "Hot Streak" : "Good";
  if (!w.personality) w.personality = (w.hot || 0) > 2 ? "Face" : "Heel";
  if (!w.style) w.style = (w.inRing || 70) > 82 ? "Powerhouse" : (w.charisma || 60) > 80 ? "Showman" : "Technician";
  if (!w.finishers || w.finishers.length === 0) {
    w.finishers = [{ name: "Signature Move", grade: "A", baseDamage: 20, scaling: 1.4 }];
  }
  if (!w.history) w.history = { titles: [], rivalries: [], winRate: "55%" };
  if (!w.tier) w.tier = (w.popularity || 60) > 85 ? "Main Event" : (w.popularity || 60) > 70 ? "Upper Midcard" : "Midcard";
  return w;
}

function signFreeAgent(name, targetBrand = "Meltdown") {
  const template = wrestlerDatabase[name];
  if (!template) { alert(`No wrestler named ${name} in database`); return false; }

  const cost = Math.floor(8000 + (template.popularity || 60) * 120);
  if (!spendBrandMoney(targetBrand, cost, `Signing ${name}`)) return false;

  // Remove from Free Agents if already on roster
  game.wrestlers = game.wrestlers.filter(w => w.name !== name);

  const newWrestler = spawnWrestlerFromDB(name, { brand: targetBrand });
  if (!newWrestler) return false;

  migrateWrestlerToNewSchema(newWrestler);
  game.wrestlers.push(newWrestler);

  JPE_LOG.roster(`Signed ${name} to ${targetBrand} for $${cost.toLocaleString()}`);
  saveGame();
  if (currentTab === 1) showTab(1); // refresh Roster
  return true;
}

function getFreeAgents() {
  return Object.values(wrestlerDatabase)
    .filter(t => t.brand === "Free Agents" || !game.wrestlers.find(w => w.name === t.name))
    .map(t => t.name);
}

const SAVE_KEY = "jpeWrestlingGM_v38";
const SAVE_VERSION = 83; // bumped for v83 overhaul
let storageAvailable = true;
function saveGame() {
    if (!storageAvailable) return;
    try { localStorage.setItem(SAVE_KEY, JSON.stringify({ version: SAVE_VERSION, game })); } catch(e){}
}

// === v83 SAVE/LOAD OVERHAUL (Phase 1.1) ===
// Clear version, step-by-step migration, validation, export/import.
// Core save is the main game state. (Meta save for settings can be added later.)

function validateSave(parsed) {
    if (!parsed || typeof parsed !== 'object' || !parsed.game) {
        console.error('[Save] Validation failed: no game object');
        return false;
    }
    const g = parsed.game;
    if (!Array.isArray(g.wrestlers) || g.wrestlers.length === 0) {
        console.error('[Save] Validation failed: no wrestlers');
        return false;
    }
    if (typeof g.money !== 'number' || typeof g.popularity !== 'number') {
        console.error('[Save] Validation failed: bad money/pop');
        return false;
    }
    // add more checks as needed
    return true;
}

function migrateSave(parsed) {
    if (!parsed || !parsed.game) return false;

    const saveVersion = parsed.version || 0;
    let migrated = false;

    // Step-by-step upgrades (add new if (saveVersion < N) blocks for future)
    if (saveVersion < 43) {
        if (!parsed.game.brandMoney) {
            parsed.game.brandMoney = { meltdown: 65000, grandSlam: 52000, gamma: 38000 };
        }
        JPE_LOG.info(`Migrated save from v${saveVersion} -> v43 (brandMoney)`);
        migrated = true;
    }
    if (saveVersion < 50) {
        if (!parsed.game.uncollectedMerch) parsed.game.uncollectedMerch = 0;
        if (typeof parsed.game.lastMerchCollectionDay !== 'number') parsed.game.lastMerchCollectionDay = 0;
        JPE_LOG.info(`Migrated save from v${saveVersion} -> v50 (merch interest fields)`);
        migrated = true;
    }
    if (saveVersion < 83) {
        // ensure new fields from v83 patches
        parsed.game.cold_streak = parsed.game.cold_streak || 0;
        parsed.game.merchModifier = parsed.game.merchModifier || 1;
        if (!parsed.game.trainingLog) parsed.game.trainingLog = [];
        JPE_LOG.info(`Migrated save from v${saveVersion} -> v83 (new fields)`);
        migrated = true;
    }

    // Always ensure critical structures
    if (!parsed.game.weeklyRecaps) parsed.game.weeklyRecaps = [];
    if (!parsed.game.showEarningsLog) parsed.game.showEarningsLog = [];
    if (!parsed.game.devLog) parsed.game.devLog = {}; // per wrestler in profile

    if (migrated) {
        parsed.version = SAVE_VERSION; // update version after migration
    }
    return true;
}

function loadGame() {
    try {
        const raw = localStorage.getItem(SAVE_KEY);
        if (!raw) return false;
        const parsed = JSON.parse(raw);
        if (parsed && parsed.game) {
            if (!validateSave(parsed)) {
                console.warn('[Save] Corrupted save detected - ignoring load');
                return false;
            }
            migrateSave(parsed);
            // deep merge-ish: assign top level, but for arrays/objects be careful
            Object.keys(parsed.game).forEach(k => {
                game[k] = parsed.game[k];
            });
            JPE_LOG.info(`Loaded save v${parsed.version || 0}`);
            return true;
        }
    } catch(e) {
        console.error('[Save] Load error', e);
    }
    return false;
}

// Export/Import JSON backup
function exportSave() {
    try {
        const payload = { version: SAVE_VERSION, game: JSON.parse(JSON.stringify(game)) };
        const json = JSON.stringify(payload, null, 2);
        const blob = new Blob([json], {type: 'application/json'});
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `jpe-save-v${SAVE_VERSION}-${new Date().toISOString().slice(0,10)}.json`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
        JPE_LOG.info('Save exported');
    } catch(e) { console.error('Export failed', e); }
}

function importSave(jsonString) {
    try {
        const parsed = JSON.parse(jsonString);
        if (!validateSave(parsed)) {
            alert('Invalid or corrupted save JSON');
            return false;
        }
        migrateSave(parsed);
        Object.keys(parsed.game).forEach(k => { game[k] = parsed.game[k]; });
        saveGame();
        alert('Save imported successfully. Reloading...');
        location.reload();
        return true;
    } catch(e) {
        alert('Import failed: ' + e.message);
        return false;
    }
}

function hardReset() {
    if (confirm("Permanently erase all progress and reset to defaults?")) {
        localStorage.removeItem(SAVE_KEY);
        location.reload();
    }
}

